using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class AddSheriffServiceMats
{
 const string D="Assets/Prefabs/Workshop/Sheriff/";
 static Material Mat(string n,Color c){var m=new Material(Shader.Find("Standard")){name=n,color=c};m.SetFloat("_Glossiness",.1f);AssetDatabase.CreateAsset(m,D+n+".mat");return m;}
 static Transform Group(string n,Transform p){var t=new GameObject(n).transform;t.SetParent(p,false);return t;}
 static GameObject Box(string n,Transform p,Vector3 pos,Vector3 size,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(p,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static Transform Rug(string n,Transform p,Vector3 center,Vector2 size,Material cloth,Material border,string words,Material font){var t=Group(n,p);t.localPosition=center;Box("Service_Rug",t,Vector3.zero,new Vector3(size.x,.018f,size.y),cloth);foreach(float side in new[]{-1f,1f}){Box("Rug_Side_Trim",t,new Vector3(side*(size.x*.5f-.04f),.011f,0),new Vector3(.045f,.005f,size.y-.045f),border);Box("Rug_End_Trim",t,new Vector3(0,.011f,side*(size.y*.5f-.04f)),new Vector3(size.x-.045f,.005f,.045f),border);}var label=Group("Rug_Label",t);label.localPosition=new Vector3(0,.015f,0);label.localRotation=Quaternion.Euler(90,0,0);var tm=label.gameObject.AddComponent<TextMesh>();tm.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");tm.fontSize=64;tm.characterSize=.05f;tm.anchor=TextAnchor.MiddleCenter;tm.alignment=TextAlignment.Center;tm.color=new Color(.92f,.84f,.67f);tm.text=words;var r=label.GetComponent<Renderer>();r.sharedMaterial=font;if(r.localBounds.size.x>size.x-.2f)tm.characterSize*=(size.x-.2f)/r.localBounds.size.x;return t;}
 static void Capture(Transform h){var go=new GameObject("Temporary_Sheriff_Mats_Camera");var rt=new RenderTexture(1500,1100,24);var tex=new Texture2D(1500,1100,TextureFormat.RGB24,false);var previous=RenderTexture.active;var canvases=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.enabled).ToArray();try{foreach(var c in canvases)c.enabled=false;var cam=go.AddComponent<Camera>();cam.transform.position=h.TransformPoint(new Vector3(0,2.02f,-2.6f));cam.transform.LookAt(h.TransformPoint(new Vector3(.1f,1.1f,.3f)));cam.fieldOfView=110;cam.farClipPlane=120;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.19f,.25f,.29f);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1500,1100),0,0);tex.Apply();File.WriteAllBytes("Docs/assets/examples/Sheriff_Service_Mats.png",tex.EncodeToPNG());}finally{foreach(var c in canvases)c.enabled=true;RenderTexture.active=previous;UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}}
 public static string Main(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/CastleServicesWorkshop.unity"||scene.isDirty||EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Saved castle Edit Mode required");if(!File.Exists("Library/WorkshopBackups/DB-ON-082/OwnerSaved.unity"))throw new Exception("Owner checkpoint required");var h=GameObject.Find("Castle_Services_Prototype").transform.Find("03_Service_Houses/05_Nursery");if(h.Find("21_Sheriff_Service_Mats")!=null)throw new Exception("Already added; preserve edits");var gate=h.Find("19_Compact_Prison/Gate_Locked");var poster=h.Find("20_Sheriff_Decor/Wanted_Poster");var font=h.Find("13_Service_Sign/Service_Name").GetComponent<Renderer>().sharedMaterial;var deliveryCloth=Mat("Sheriff_DeliveryRug",new Color(.31f,.17f,.13f));var rewardCloth=Mat("Sheriff_RewardRug",new Color(.13f,.28f,.26f));var border=AssetDatabase.LoadAssetAtPath<Material>(D+"Sheriff_LockBrass.mat");var group=Group("21_Sheriff_Service_Mats",h);
  var door=gate.GetComponent<BoxCollider>();var doorCenter=h.InverseTransformPoint(gate.TransformPoint(door.center));var deliveryCenter=new Vector3(doorCenter.x,.49f,doorCenter.z-.62f);var posterPosition=h.InverseTransformPoint(poster.position);var rewardCenter=new Vector3(posterPosition.x-.66f,.49f,posterPosition.z);
  Rug("Prisoner_Delivery_Rug",group,deliveryCenter,new Vector2(1.1f,1.03f),deliveryCloth,border,"СДАЧА",font);Rug("Bounty_Reward_Rug",group,rewardCenter,new Vector2(1.12f,1.02f),rewardCloth,border,"НАГРАДА",font);
  var sell=h.Find("15_Gameplay_Source/SellPoint");var money=sell.GetComponentsInChildren<Transform>(true).First(t=>t.name=="MoneyBagPoint");var trigger=sell.GetComponent<BoxCollider>();sell.position=h.TransformPoint(new Vector3(deliveryCenter.x,.48f,deliveryCenter.z));trigger.center=new Vector3(0,.7f,0);trigger.size=new Vector3(1.1f,1.4f,1.03f);trigger.isTrigger=true;money.position=h.TransformPoint(rewardCenter+Vector3.up*.01f);PrefabUtility.RecordPrefabInstancePropertyModifications(sell);PrefabUtility.RecordPrefabInstancePropertyModifications(trigger);PrefabUtility.RecordPrefabInstancePropertyModifications(money);
  Physics.SyncTransforms();var contact=Physics.OverlapBox(h.TransformPoint(deliveryCenter+Vector3.up*.35f),new Vector3(.1f,.2f,.1f),h.rotation,~0,QueryTriggerInteraction.Collide);if(!contact.Contains(trigger))throw new Exception("Delivery rug does not contact SellPoint");if((h.InverseTransformPoint(money.position)-rewardCenter-Vector3.up*.01f).magnitude>.001f)throw new Exception("Reward not aligned with rug");
  var probe=new GameObject("Temporary_Sheriff_Rug_Probe");string paths="";try{var cc=probe.AddComponent<CharacterController>();cc.height=1.8f;cc.radius=.35f;cc.center=new Vector3(0,.9f,0);cc.stepOffset=.3f;foreach(var target in new[]{deliveryCenter,rewardCenter}){probe.transform.position=h.TransformPoint(new Vector3(0,.55f,-4.5f));Physics.SyncTransforms();for(int i=0;i<95;i++)cc.Move(h.TransformVector(new Vector3(0,0,.04f))+Vector3.down*.025f);float dx=target.x;for(int i=0;i<60;i++){float remain=dx-h.InverseTransformPoint(probe.transform.position).x;if(Mathf.Abs(remain)<.03f)break;cc.Move(h.TransformVector(new Vector3(Mathf.Clamp(remain,-.04f,.04f),0,0))+Vector3.down*.025f);}float dz=target.z;for(int i=0;i<45;i++){float remain=dz-h.InverseTransformPoint(probe.transform.position).z;if(Mathf.Abs(remain)<.03f)break;cc.Move(h.TransformVector(new Vector3(0,0,Mathf.Clamp(remain,-.04f,.04f)))+Vector3.down*.025f);}var p=h.InverseTransformPoint(probe.transform.position);if(Vector2.Distance(new Vector2(p.x,p.z),new Vector2(target.x,target.z))>.2f||!cc.isGrounded)throw new Exception("Rug approach blocked "+p+" -> "+target);paths+=p+"; ";}}finally{UnityEngine.Object.DestroyImmediate(probe);}
  Capture(h);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");Selection.activeGameObject=h.gameObject;var report="PASS: owner checkpoint retained; surrender rug "+deliveryCenter+" aligned with original SellPoint; reward rug "+rewardCenter+" under current wanted poster; MoneyBagPoint on reward rug; player approaches both rugs: "+paths+". Existing accumulation/collection logic unchanged; actual surrender/reward collection untested (Fusion unavailable).";File.WriteAllText("Docs/assets/examples/SHERIFF_SERVICE_MATS_VALIDATION.txt",report);return report;
 }
}
